// Источник: web-тест .qa/e2e/tests/journey/jr-06-rankup-window-not-repeated-clean-device.spec.ts, план .qa/e2e/specs/journey.md (14.11), кейс .qa/tests/journey/JR-06-rankup-window-not-repeated-clean-device.md
// Тикет #22c9d541 (עבר QA 04.10). Опора: «מה רצוי» — признак показанного уровня в аккаунте; «כניסה ממכשיר אחר… אינה מציגה אותו שוב»; «מה קיים» — окно не перекрывает экран.
// В приложении: окно не появляется при входе в «המסע שלי», после перезапуска приложения и после ухода/возврата. Окно НЕ подавляется — это и проверяем.
// «Чистое устройство» (переустановка / очистка данных приложения) — вручную (noReset держит сессию; переустановка требует нового входа по OTP).
import { driver, expect } from '@wdio/globals';
import { byText, byTextContains, expectVisibleText, scrollToText } from '../../helpers/ui.ts';
import { goTab } from '../../helpers/nav.ts';
import { toHome } from '../../helpers/app.ts';

const appId = () => (driver.isAndroid ? process.env.APP_ANDROID_PACKAGE : process.env.APP_IOS_BUNDLE) ?? '';

/** Окно «עלית דרגה» не появляется в течение окна наблюдения (опрос, без фиксированной паузы). */
async function expectNoMilestoneWindow(ms = 6000) {
  const deadline = Date.now() + ms;
  while (Date.now() < deadline) {
    expect(await (await byTextContains('עלית דרגה')).isDisplayed().catch(() => false)).toBe(false);
  }
}
async function openJourney() {
  await goTab('המסע שלי');
  await (await byText('המסע שלי')).waitForDisplayed({ timeout: 20000 });
  await (await byText('דרגה 10 מתוך 10')).waitForDisplayed({ timeout: 20000 });  // предусловие: уровень 10, повышения быть не может
}

describe('«המסע שלי»', () => {
  afterEach(async () => { await toHome(); });

  it('JR-06 Окно «עלית דרגה» не показывается повторно без повышения (user1, уровень 10) #22c9d541 @prod-safe', async () => {
    // 1. Первое открытие «המסע שלי» — окна нет.
    await openJourney();
    await expectNoMilestoneWindow();

    // 2. Перезапуск приложения (аналог reload) — окна нет.
    await driver.terminateApp(appId());
    await driver.activateApp(appId());
    await (await byText('בית')).waitForDisplayed({ timeout: 30000 });
    await openJourney();
    await expectNoMilestoneWindow();

    // 3. «בית» и обратно — окна нет.
    await goTab('בית');
    await expectVisibleText('תזכורות מהירות');
    await openJourney();
    await expectNoMilestoneWindow();

    // 4. Экран не перекрыт — «צפה בהכל» открывает историю.
    await (await scrollToText('צפה בהכל')).click();
    await expect(byText('מפת השפעה')).not.toBeDisplayed();
  });
});
